import limited_client as robot,numpy as np

def obj(o):
 a=o['rgb'].astype(int); d=o['depth_m']; K=o['intrinsic']; M=o['camera_to_world']; yy,xx=np.indices(a.shape[:2]); m=(a[:,:,2]>a[:,:,0]*1.3)&(a[:,:,2]>a[:,:,1]*1.15)&(a[:,:,2]>70)&(xx>175)&(xx<270)&(yy<220); y,x=np.where(m); pts=[]
 for u,v in zip(x,y):
  z=float(d[v,u]);
  if z<2:
   pts.append(M[:3,:3]@np.array([(u-240)*z/K[0,0],(v-240)*z/K[1,1],z])+M[:3,3])
 if pts:
  p=np.array(pts); return len(p),np.round(p.mean(0),3), np.round([p.min(0),p.max(0)],3)
 return 0,None,None
b=robot.observe('corner4');print('before',obj(b))
for i in range(4):robot.step([1,0,0,-1])
for i in range(5):robot.step([0,0,0,-1])
a=robot.observe('corner4');print(robot.status(),'tcp',a['robot']['tcp_position'],'target',a['robot']['mocap_target_position']);print('after',obj(a))
